# ==============================================================================# IOTEC MISSION CONTROL# 014_API_ROUTER.py# ==============================================================================import sqlite3import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS api_routes(    id INTEGER PRIMARY KEY AUTOINCREMENT,    endpoint TEXT,    method TEXT,    description TEXT,    enabled INTEGER,    created_at TEXT)""")conn.commit()ROTAS = [("/api/status","GET","Status Geral"),("/api/missions","GET","Lista MissÃµes"),("/api/events","GET","Lista Eventos"),("/api/logs","GET","Logs"),("/api/maestro","GET","Status Maestro"),("/api/health","GET","Health Check"),("/api/services","GET","ServiÃ§os"),("/api/database","GET","Banco")]for endpoint,method,description in ROTAS:    cur.execute(        "SELECT id FROM api_routes WHERE endpoint=?",        (endpoint,)    )    if cur.fetchone() is None:        cur.execute("""        INSERT INTO api_routes(            endpoint,            method,            description,            enabled,            created_at        )        VALUES(?,?,?,?,?)        """,(            endpoint,            method,            description,            1,            datetime.now().isoformat()        ))conn.commit()cur.execute("SELECT * FROM api_routes")rotas=[]for r in cur.fetchall():    rotas.append(dict(r))print("="*80)print("API ROUTER")print("="*80)print(json.dumps(rotas,indent=4,ensure_ascii=False))print("="*80)conn.close()

